<script setup lang="ts">
import {onBeforeUnmount,ref} from 'vue';
import ClientPreparation from './ClientPreparation.vue';
import ClientDocuments from './ClientDocuments.vue';
import AppDialog from './AppDialog.vue';
const props=defineProps<{id:number;canEdit:boolean;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
const emit=defineEmits<{close:[];edit:[]}>();
type Detail={razao_social:string;nome_fantasia:string;cnpj:string;municipio:string;uf:string;ativo:boolean;modo_envio:string;contatos:Array<{contato_id:number;nome:string;email:string;funcao:string;receber_email:boolean;tipos:string[]}>;sindicatos:Array<{sindicato_id:number;nome:string;principal:boolean;enquadramento_confirmado:boolean;categoria:string;uf:string;municipio:string}>};
const detail=ref<Detail|null>(null),error=ref('');let alive=true;
props.request<Detail>('/api/contexto/clientes/'+props.id).then(data=>{if(alive)detail.value=data;}).catch(cause=>{if(alive)error.value=cause.message;});onBeforeUnmount(()=>{alive=false;});
</script>
<template><AppDialog title="Ficha do cliente" @close="emit('close')"><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!detail" role="status">Carregando ficha…</p><template v-else><header class="client-sheet-identity"><div><span class="eyebrow">Empresa</span><h3>{{ detail.nome_fantasia||detail.razao_social }}</h3><p>{{ detail.razao_social }} · {{ detail.cnpj }}</p></div><span class="status-badge" :data-tone="detail.ativo?'success':'neutral'">{{ detail.ativo?'Ativo':'Inativo' }}</span></header><div class="client-sheet-grid"><article><h3>Dados e envio</h3><p>{{ [detail.municipio,detail.uf].filter(Boolean).join(' / ')||'Localidade não informada' }}</p><p>{{ detail.ativo?'Cliente ativo':'Cliente inativo' }}</p><p>{{ detail.modo_envio==='automatico'?'Automático conforme regras':'Revisar antes de enviar' }}</p></article><article><h3>Contatos vinculados</h3><p v-if="!detail.contatos.length">Nenhum contato vinculado.</p><section v-for="item in detail.contatos" :key="item.contato_id"><strong>{{ item.nome }}</strong><p>{{ item.email }} · {{ item.funcao||'Função não informada' }}</p><p>{{ item.receber_email?'Recebe e-mail':'E-mail desativado' }} · {{ item.tipos.join(', ')||'Todos os tipos' }}</p></section></article><article><h3>Enquadramento sindical</h3><p v-if="!detail.sindicatos.length">Nenhum sindicato vinculado.</p><section v-for="item in detail.sindicatos" :key="item.sindicato_id"><strong>{{ item.nome }}</strong><p>{{ item.principal?'Principal':'Complementar' }} · {{ item.enquadramento_confirmado?'Enquadramento confirmado':'Conferir enquadramento' }}</p><p>{{ [item.categoria,item.municipio,item.uf].filter(Boolean).join(' · ') }}</p></section></article></div><ClientDocuments :can-edit="canEdit" :id="id" :request="request" :download="download" /><ClientPreparation :id="id" :active="detail.ativo" :mode="detail.modo_envio" :can-edit="canEdit" :request="request" /><footer><button v-if="canEdit" class="secondary" type="button" @click="emit('edit')">Editar cliente</button></footer></template></AppDialog></template>
